class CircularDependencyError(Exception):
    """Raised when a circular dependency is detected."""
    pass


class DependencyResolver:
    def resolve(self, dependencies: dict[str, list[str]]) -> list[list[str]]:
        """
        Resolves task dependencies into parallel execution stages.

        :param dependencies: Mapping of task_name -> list of task_names it depends on.
        :return: A list of stages, where each stage is a sorted list of tasks runnable in parallel.
        :raises CircularDependencyError: If a circular dependency or self-loop exists.
        """
        # Collect all unique tasks present in keys and dependency lists
        all_tasks = set(dependencies.keys())
        for deps in dependencies.values():
            all_tasks.update(deps)

        if not all_tasks:
            return []

        # dependents: task -> set of tasks that depend on it
        dependents: dict[str, set[str]] = {task: set() for task in all_tasks}
        # in_degree: number of unresolved dependencies for each task
        in_degree: dict[str, int] = {}

        for task in all_tasks:
            task_deps = set(dependencies.get(task, []))
            in_degree[task] = len(task_deps)
            for dep in task_deps:
                dependents[dep].add(task)

        # Stage 0: tasks with no dependencies
        current_stage = [task for task, count in in_degree.items() if count == 0]
        stages: list[list[str]] = []
        resolved_count = 0

        while current_stage:
            current_stage.sort()
            stages.append(current_stage)
            resolved_count += len(current_stage)

            next_stage: list[str] = []
            for task in current_stage:
                for dependent in dependents[task]:
                    in_degree[dependent] -= 1
                    if in_degree[dependent] == 0:
                        next_stage.append(dependent)

            current_stage = next_stage

        if resolved_count < len(all_tasks):
            raise CircularDependencyError("Circular dependency detected.")

        return stages
