class DependencyResolver:
    def resolve(self, dependencies: dict[str, list[str]]) -> list[list[str]]:
        tasks = set(dependencies)
        for prerequisites in dependencies.values():
            tasks.update(prerequisites)

        prerequisites_by_task = {
            task: set(dependencies.get(task, []))
            for task in tasks
        }

        dependents = {task: set() for task in tasks}
        for task, prerequisites in prerequisites_by_task.items():
            for prerequisite in prerequisites:
                dependents[prerequisite].add(task)

        remaining_dependencies = {
            task: len(prerequisites)
            for task, prerequisites in prerequisites_by_task.items()
        }

        ready = sorted(
            task for task, count in remaining_dependencies.items() if count == 0
        )
        stages = []
        resolved_count = 0

        while ready:
            stages.append(ready)
            resolved_count += len(ready)
            next_ready = []

            for task in ready:
                for dependent in dependents[task]:
                    remaining_dependencies[dependent] -= 1
                    if remaining_dependencies[dependent] == 0:
                        next_ready.append(dependent)

            ready = sorted(next_ready)

        if resolved_count != len(tasks):
            raise CircularDependencyError("Circular dependency detected")

        return stages
